import React from 'react';
import './education.css';

function Education() {
  return (
    <section id="education" className="section">
      <h2>Education</h2>
      <p>
        <strong>Bachelor of Science (Computer Science and Statistics)</strong>
        <br />
        Aditya Degree College, affiliated to Adhikavi Nannaya University, Kakinada, Andhra Pradesh
      </p>
    </section>
  );
}

export default Education;
